bool StockChecks::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("check_no"))
    {
        if(!validJsonOfField(1, "check_no", pJson["check_no"], err, true))
            return false;
    }
    else
    {
        err="The check_no column cannot be null";
        return false;
    }
    if(pJson.isMember("warehouse_id"))
    {
        if(!validJsonOfField(2, "warehouse_id", pJson["warehouse_id"], err, true))
            return false;
    }
    else
    {
        err="The warehouse_id column cannot be null";
        return false;
    }
    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(3, "status", pJson["status"], err, true))
            return false;
    }
    if(pJson.isMember("remark"))
    {
        if(!validJsonOfField(4, "remark", pJson["remark"], err, true))
            return false;
    }
    else
    {
        err="The remark column cannot be null";
        return false;
    }
    if(pJson.isMember("created_by"))
    {
        if(!validJsonOfField(5, "created_by", pJson["created_by"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(6, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("updated_at"))
    {
        if(!validJsonOfField(7, "updated_at", pJson["updated_at"], err, true))
            return false;
    }
    return true;
}
